mapper.select:
SELECT m.ID AS id, m.Nombre AS nombre, m.Apellidos AS apellidos, m.Activo AS activo
  FROM medicos m
 WHERE m.ID IN #{id}

SELECT DISTINCT sm.IdMedico
  FROM guardias_servicios_medicos sm
 WHERE sm.IdServicio = #{servicioId}
   AND sm.IdMedico IN #{id}

SELECT h.IdMedico AS medicoId, h.Tipo AS tipo, h.SubTipo AS subTipo, h.Desde AS desde, h.Hasta AS hasta
  FROM medicos_tipo_historico h
 WHERE h.IdMedico IN #{id}
